import asyncio
import time
from enum import Enum
from dataclasses import dataclass, field
from typing import AsyncIterator, Optional


class ErrorType(Enum):
    TIMEOUT = "timeout"
    RATE_LIMIT = "rate_limit"
    CONTEXT_LENGTH = "context_length"
    CONTENT_SAFETY = "content_safety"
    SERVER_ERROR = "server_error"
    PARAM_ERROR = "param_error"


@dataclass
class CircuitBreaker:
    failure_threshold: int = 5
    cooldown_seconds: float = 30.0
    probe_count: int = 1
    failures: int = 0
    last_failure_time: float = 0.0
    is_open: bool = False

    def record_failure(self):
        self.failures += 1
        self.last_failure_time = time.monotonic()
        if self.failures >= self.failure_threshold:
            self.is_open = True

    def record_success(self):
        self.failures = 0
        self.is_open = False

    def should_allow(self) -> bool:
        if not self.is_open:
            return True
        # cooldown 后放探测请求
        if time.monotonic() - self.last_failure_time > self.cooldown_seconds:
            return True
        return False


class RetryableError(Exception):
    def __init__(self, error_type: ErrorType, message: str = ""):
        self.error_type = error_type
        super().__init__(message or error_type.value)


class NonRetryableError(Exception):
    def __init__(self, error_type: ErrorType, message: str = ""):
        self.error_type = error_type
        super().__init__(message or error_type.value)


# 模拟 LLM 调用接口
async def call_model(model_name: str, messages: list, stream: bool = False) -> str:
    """模拟模型调用，不同模型返回不同结果或抛不同错误"""
    if model_name == "gpt-4" and len(messages) > 10:
        raise RetryableError(ErrorType.RATE_LIMIT, "GPT-4 rate limited")
    if model_name == "claude-3":
        raise NonRetryableError(ErrorType.CONTENT_SAFETY, "Content filtered")
    if stream:
        return f"[streaming from {model_name}] " + " ".join(m.get("content", "")[:20] for m in messages)
    return f"[{model_name}] response for {len(messages)} messages"


@dataclass
class RouteConfig:
    name: str
    model: str
    priority: int
    cost_per_1k_tokens: float
    max_context_length: int
    supports_tools: bool = True
    supports_stream: bool = True


@dataclass
class ModelRouter:
    routes: list = field(default_factory=lambda: [
        RouteConfig("primary", "gpt-4", priority=1, cost_per_1k_tokens=0.06, max_context_length=128000),
        RouteConfig("secondary", "claude-3", priority=2, cost_per_1k_tokens=0.015, max_context_length=200000),
        RouteConfig("fallback", "gpt-3.5-turbo", priority=3, cost_per_1k_tokens=0.002, max_context_length=16000),
    ])
    circuit_breakers: dict = field(default_factory=dict)
    max_retries: int = 2
    retry_delay: float = 0.5

    def __post_init__(self):
        for route in self.routes:
            self.circuit_breakers[route.name] = CircuitBreaker()

    def _classify_error(self, error: Exception) -> ErrorType:
        if isinstance(error, RetryableError):
            return error.error_type
        if isinstance(error, NonRetryableError):
            return error.error_type
        if isinstance(error, asyncio.TimeoutError):
            return ErrorType.TIMEOUT
        return ErrorType.SERVER_ERROR

    def _is_retryable(self, error_type: ErrorType) -> bool:
        return error_type in (ErrorType.TIMEOUT, ErrorType.RATE_LIMIT, ErrorType.SERVER_ERROR)

    async def invoke(self, messages: list, risk_level: str = "low") -> dict:
        """级联降级路由，返回结果和路由元数据"""
        metadata = {"attempts": [], "final_route": None, "degraded": False}

        for route in sorted(self.routes, key=lambda r: r.priority):
            cb = self.circuit_breakers[route.name]
            if not cb.should_allow():
                metadata["attempts"].append({"route": route.name, "status": "circuit_open"})
                continue

            # 高风险任务不能降级到 fallback 模型
            if risk_level == "high" and route.priority > 2:
                metadata["attempts"].append({"route": route.name, "status": "skip_high_risk"})
                continue

            for attempt in range(self.max_retries + 1):
                try:
                    result = await asyncio.wait_for(
                        call_model(route.model, messages),
                        timeout=30.0
                    )
                    cb.record_success()
                    metadata["final_route"] = route.name
                    if route.priority > 1:
                        metadata["degraded"] = True
                    metadata["attempts"].append({"route": route.name, "attempt": attempt + 1, "status": "success"})
                    return {"result": result, "metadata": metadata}
                except Exception as e:
                    error_type = self._classify_error(e)
                    metadata["attempts"].append({
                        "route": route.name, "attempt": attempt + 1,
                        "status": "error", "error_type": error_type.value
                    })
                    if not self._is_retryable(error_type):
                        break  # 不可重试错误直接跳到下一个 route
                    if attempt < self.max_retries:
                        await asyncio.sleep(self.retry_delay * (attempt + 1))
            cb.record_failure()

        raise RuntimeError(f"All routes exhausted. Metadata: {metadata}")

    async def invoke_stream(self, messages: list, risk_level: str = "low") -> AsyncIterator[str]:
        """流式路由，主模型失败后返回已有 token 并切换"""
        partial_tokens = []
        for route in sorted(self.routes, key=lambda r: r.priority):
            cb = self.circuit_breakers[route.name]
            if not cb.should_allow():
                continue
            if risk_level == "high" and route.priority > 2:
                continue
            try:
                result = await asyncio.wait_for(
                    call_model(route.model, messages, stream=True),
                    timeout=30.0
                )
                cb.record_success()
                yield result
                return
            except Exception:
                cb.record_failure()
                continue
        if partial_tokens:
            yield "[partial] " + " ".join(partial_tokens)
        else:
            yield "[fallback] 所有模型不可用，已转人工队列"


# 使用示例
async def main():
    router = ModelRouter()
    messages = [{"role": "user", "content": "帮我分析这段代码"}]

    # 普通请求：级联降级
    result = await router.invoke(messages, risk_level="low")
    print(f"Result: {result['result']}")
    print(f"Metadata: {result['metadata']}")

    # 高风险请求：不降级到低质量模型
    result = await router.invoke(messages, risk_level="high")
    print(f"High-risk result: {result['result']}")
    print(f"Metadata: {result['metadata']}")

    # 流式请求
    async for chunk in router.invoke_stream(messages):
        print(f"Stream: {chunk}")


if __name__ == "__main__":
    asyncio.run(main())
